        "full": "Концепция: не усложнять сознательно, еда вкусная и быстро-сборная. Луковый суп: «адское месиво из сыра, лука, хлеба, мощный аромат — я переехал во Францию с одной ложки». Почки кролика с луковым пармантье и изюмом: интересный тактильный опыт, «блюдо со спецэффектами». Пт де фуагра, маринованная в белом вине, с хересом и черносливом на бриоши — «безобразие какое-то». Говяжий язык с печёным пастернаком: слои мягкости от языка к груше и пюре — «капец как необычно». Бёф бургиньон из щеки: томлёная до состояния «можно раздавить языком», растворяется во рту. Пончики с тартаром из говядины, сыром пикарин и чёрным трюфелем: пончик под завязку набит соусом — «одно из лучших блюд за день». Карпаччо из рибая с трюфельным соусом: «сырое мясо, которое во рту растаяло». Голубец из утки с фуагра: жирная котлетка из белого мяса, картошка конфи по-домашнему. Питивер с рапаном и белыми грибами: неожиданный морепродуктово-грибной пирог — «на любителя, второй раз не закажу». Фермерский салат: томатный тест пройден, с сыром бомба. Десерты: шоколадный мусс с вишней — «стопроцентное попадание»; кокосовый с малиной — мимо, мусс безвкусный.",
